// app/robots.ts - Sinh robots.txt động trong Next.js App Router (TypeScript)
import type { MetadataRoute } from 'next';

export default function robots(): MetadataRoute.Robots {
  const baseUrl = process.env.NEXT_PUBLIC_SITE_URL || 'https://mystore.vn';

  return {
    rules: [
      {
        userAgent: '*',
        allow: '/',
        disallow: [
          '/cart/',
          '/checkout/',
          '/api/',
          '/admin/',
          '/search*',
          '/*?*utm_*', // Chặn crawl các URL gắn param marketing
        ],
      },
      {
        // Chặn hoàn toàn các crawler AI thu thập dữ liệu nếu doanh nghiệp yêu cầu
        userAgent: ['GPTBot', 'CCBot'],
        disallow: ['/'],
      }
    ],
    sitemap: `${baseUrl}/sitemap.xml`,
  };
}

// app/sitemap.ts - Sinh Sitemap XML động trong Next.js App Router (TypeScript)
import type { MetadataRoute } from 'next';
import { fetchLatestArticles } from '@/lib/api/articles';

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const baseUrl = 'https://devpro.vn';
  const articles = await fetchLatestArticles({ limit: 1000 });

  const articleUrls: MetadataRoute.Sitemap = articles.map((article) => ({
    url: `${baseUrl}/blog/${article.slug}`,
    lastModified: new Date(article.updatedAt),
    changeFrequency: 'weekly',
    priority: 0.8,
  }));

  return [
    {
      url: baseUrl,
      lastModified: new Date(),
      changeFrequency: 'daily',
      priority: 1.0,
    },
    {
      url: `${baseUrl}/courses`,
      lastModified: new Date(),
      changeFrequency: 'weekly',
      priority: 0.9,
    },
    ...articleUrls,
  ];
}

