// Đo lường và báo cáo Core Web Vitals thời gian thực (TypeScript)
import { onCLS, onINP, onLCP, Metric } from 'web-vitals';

function sendToAnalytics(metric: Metric) {
  const body = JSON.stringify({
    name: metric.name,
    value: metric.value,
    rating: metric.rating, // 'good' | 'needs-improvement' | 'poor'
    delta: metric.delta,
    id: metric.id,
    page: window.location.pathname,
  });

  // Sử dụng sendBeacon để đảm bảo gửi dữ liệu an toàn kể cả khi người dùng rời trang
  if (navigator.sendBeacon) {
    navigator.sendBeacon('/api/analytics/vitals', body);
  } else {
    fetch('/api/analytics/vitals', { body, method: 'POST', keepalive: true });
  }
}

// Kích hoạt theo dõi cả 3 chỉ số cốt lõi
export function reportWebVitals() {
  onLCP(sendToAnalytics);
  onINP(sendToAnalytics);
  onCLS(sendToAnalytics);
}

// Component nhúng Schema JSON-LD cho trang Sản phẩm (Next.js / React)
import React from 'react';

interface ProductJsonLdProps {
  product: {
    name: string;
    description: string;
    imageUrl: string;
    sku: string;
    price: number;
    currency: string;
    ratingValue: number;
