  };
}

// app/sitemap.ts - Phân trang Sitemap tự động cho 100.000 tin tuyển dụng
import type { MetadataRoute } from 'next';

const ITEMS_PER_SITEMAP = 50000;

// 1. Sinh danh sách các sitemap con dựa trên tổng số lượng bản ghi
export async function generateSitemaps() {
  const totalJobs = await fetchJobCount();
  const numberOfSitemaps = Math.ceil(totalJobs / ITEMS_PER_SITEMAP);

  return Array.from({ length: numberOfSitemaps }, (_, index) => ({ id: index }));
}

// 2. Trả về URLs cho sitemap con cụ thể dựa vào id
export default async function sitemap({
  id,
}: { id: number }): Promise<MetadataRoute.Sitemap> {
  const start = id * ITEMS_PER_SITEMAP;
  const jobs = await fetchJobsChunk({ skip: start, limit: ITEMS_PER_SITEMAP });

  return jobs.map((job) => ({
    url: `https://jobportal.vn/jobs/${job.slug}`,
    lastModified: new Date(job.updatedAt),
    changeFrequency: 'daily',
    priority: 0.7,
  }));
}

