// Tiện ích chuẩn hóa Slug chuẩn SEO cho URL (TypeScript)
export function generateSeoSlug(title: string): string {
  return title
    .toLowerCase()
    .normalize('NFD') // Tách tổ hợp ký tự có dấu
    .replace(/[\u0300-\u036f]/g, '') // Xóa toàn bộ dấu phụ tiếng Việt
    .replace(/[đĐ]/g, 'd') // Chuẩn hóa ký tự đ/Đ
    .replace(/[^a-z0-9\s-]/g, '') // Loại bỏ ký tự đặc biệt
    .trim()
    .replace(/\s+/g, '-') // Thay khoảng trắng bằng dấu gạch ngang
    .replace(/-+/g, '-'); // Tránh lặp dấu gạch ngang liên tiếp
}

