// Next.js Edge Middleware chặn Crawler lọt vào bẫy Faceted Search gây lãng phí Crawl Budget
import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/request';

const SEARCH_BOT_REGEX = /Googlebot|bingbot|Baiduspider|YandexBot/i;

export function middleware(request: NextRequest) {
  const userAgent = request.headers.get('user-agent') || '';
  const isBot = SEARCH_BOT_REGEX.test(userAgent);
  const { searchParams, pathname } = request.nextUrl;

  // Nếu bot truy cập vào danh mục có từ 2 tham số bộ lọc trở lên
  const filterParamCount = Array.from(searchParams.keys()).filter((key) =>
    ['color', 'size', 'price', 'brand', 'order'].includes(key)
  ).length;

  if (isBot && filterParamCount >= 2) {
    // Trả về header X-Robots-Tag: noindex hoặc chuyển hướng về canonical URL gốc
    const response = NextResponse.next();
    response.headers.set('X-Robots-Tag', 'noindex, nofollow');
    return response;
  }

  return NextResponse.next();
}

