// Script tự động hóa kiểm tra Technical SEO trong CI pipeline bằng Playwright (TypeScript)
import { test, expect } from '@playwright/test';

test.describe('Kiểm tra Technical SEO tự động trước khi Deploy', () => {
  test('Trang chi tiết sản phẩm phải tuân thủ chuẩn SEO cốt lõi', async ({ page }) => {
    const response = await page.goto('/products/ao-khoac-nam');

    // 1. Phải trả về mã trạng thái HTTP 200
    expect(response?.status()).toBe(200);

    // 2. Phải có đúng 1 thẻ H1 duy nhất
    const h1Count = await page.locator('h1').count();
    expect(h1Count).toBe(1);

    // 3. Phải có canonical URL hợp lệ và là tuyệt đối
    const canonical = await page.locator('link[rel="canonical"]').getAttribute('href');
    expect(canonical).toMatch(/^https:\/\/mystore\.vn\/products\/[a-z0-9-]+$/);

    // 4. Kiểm tra dữ liệu có cấu trúc JSON-LD Product hợp lệ
    const jsonLdScript = await page.locator('script[type="application/ld+json"]').textContent();
    expect(jsonLdScript).toBeTruthy();
    const parsedSchema = JSON.parse(jsonLdScript!);
    expect(parsedSchema['@type']).toBe('Product');
    expect(parsedSchema.offers.price).toBeGreaterThan(0);

    // 5. Toàn bộ ảnh nội dung phải có thẻ alt
    const imagesWithoutAlt = await page.locator('img:not([alt])').count();
    expect(imagesWithoutAlt).toBe(0);
  });
});
